{
  "name": "通用通信端口",
  "name_en": "Generic Communication Port",
  "manufacturer": "",
  "description": "用于实验仪器与计算机之间进行字节流或文本命令通信的通用通信端口，可完成连接管理、数据收发、缓冲区刷新以及基于模式的应答读取，常用于控制和读取带串行或类似命令接口的实验设备。",
  "description_en": "A general communication port used for byte-stream or text-command communication between a computer and laboratory instruments. It supports connection management, data transfer, buffer flushing, and pattern-based reply reading, and is commonly used to control and read instruments with serial or similar command interfaces.",
  "tag_hints": [
    "serial communication",
    "instrument control",
    "ASCII command protocol",
    "byte stream I/O",
    "pattern-matched replies"
  ],
  "actions": [
    {
      "action_name": "auto-isOpen",
      "description": "检查通信端口是否已打开。",
      "description_en": "Check whether the communication port is open."
    },
    {
      "action_name": "auto-isNotOpen",
      "description": "检查通信端口是否未打开。",
      "description_en": "Check whether the communication port is not open."
    },
    {
      "action_name": "auto-open",
      "description": "打开通信端口。",
      "description_en": "Open the communication port."
    },
    {
      "action_name": "auto-close",
      "description": "关闭通信端口。",
      "description_en": "Close the communication port."
    },
    {
      "action_name": "auto-bytesAvailable",
      "description": "查询当前可读取的字节数。",
      "description_en": "Query the number of bytes currently available to read."
    },
    {
      "action_name": "auto-flush",
      "description": "刷新通信缓冲区。",
      "description_en": "Flush the communication buffers."
    },
    {
      "action_name": "auto-readData",
      "description": "读取指定长度的原始数据。",
      "description_en": "Read raw data of the specified length."
    },
    {
      "action_name": "auto-writeData",
      "description": "写入原始数据。",
      "description_en": "Write raw data."
    },
    {
      "action_name": "auto-readString",
      "description": "读取一条字符串消息。",
      "description_en": "Read a string message."
    },
    {
      "action_name": "auto-writeString",
      "description": "写入一条字符串消息。",
      "description_en": "Write a string message."
    },
    {
      "action_name": "auto-writeStringExpectMatchingString",
      "description": "发送字符串并等待匹配指定模式的回复。",
      "description_en": "Send a string and wait for a reply matching the specified pattern."
    },
    {
      "action_name": "auto-writeStringReadFirstMatchingGroup",
      "description": "发送字符串并读取回复中第一个匹配分组。",
      "description_en": "Send a string and read the first matching group from the reply."
    },
    {
      "action_name": "auto-writeStringReadMatchingGroups",
      "description": "发送字符串并读取回复中的匹配分组。",
      "description_en": "Send a string and read matching groups from the reply."
    },
    {
      "action_name": "auto-readMatchingGroups",
      "description": "从接收到的数据中读取匹配模式的分组。",
      "description_en": "Read groups matching a pattern from received data."
    }
  ]
}

